  /**
   * Calcula el total de abonos que se encuentran entre dos fechas.
   *
   * @param {Date | string} fechaInicio - La fecha de inicio para filtrar los abonos. Puede ser un objeto Date o una cadena de texto.
   * @param {Date | string} fechaFin - La fecha de fin para filtrar los abonos. Puede ser un objeto Date o una cadena de texto.
   * @returns {number} - El total de abonos que se encuentran entre las dos fechas.
   */
  public totalAbonosEntreDosFechas(
    abonos: CreditoAbono[],
    fechaInicio?: string,
    fechaFin?: string,
  ): { saldoAbonadoEnPeriodo: number; abonosEnPeriodo: CreditoAbono[] } {
    // Si no hay abonos, retornar 0
    if (!abonos || abonos.length === 0) {
      return { saldoAbonadoEnPeriodo: 0, abonosEnPeriodo: [] };
    }

    if (fechaFin?.length == 10) {
      fechaFin += 'T17:00:00Z';
    }

    if (fechaInicio?.length == 10) {
      fechaInicio += 'T17:00:00Z';
    }

    // Convertir las fechas de inicio y fin a objetos Date si son cadenas de texto
    const fechaInicioDate = fechaInicio ? new Date(fechaInicio) : undefined;
    const fechaFinDate = fechaFin ? new Date(fechaFin) : undefined;

    // Filtrar los abonos según las fechas proporcionadas
    const abonosFiltrados = abonos.filter((abono) => {
      if (abono.fecha?.length == 10) {
        abono.fecha += 'T17:00:00Z';
      }
      const fechaAbono = new Date(abono.fecha);

      // Si solo se proporciona la fecha de inicio, filtrar desde esa fecha en adelante
      if (fechaInicioDate && !fechaFinDate) {
        return fechaAbono.getTime() > fechaInicioDate.getTime();
      }

      // Si solo se proporciona la fecha de fin, filtrar hasta esa fecha
      if (!fechaInicioDate && fechaFinDate) {
        return fechaAbono.getTime() <= fechaFinDate.getTime();
      }

      // Si se proporcionan ambas fechas, filtrar entre esas fechas
      if (fechaInicioDate && fechaFinDate) {
        return (
          fechaAbono.getTime() > fechaInicioDate.getTime() &&
          fechaAbono.getTime() <= fechaFinDate.getTime()
        );
      }

      // Si no se proporcionan fechas, retornar todos los abonos
      return true;
    });

    const totalAbonado = abonosFiltrados.reduce(
      (total, abono) => total + abono.monto,
      0,
    );
    // Calcular el total de los abonos filtrados
    return {
      saldoAbonadoEnPeriodo: totalAbonado,
      abonosEnPeriodo: abonosFiltrados,
    };
  }

  public mesesEntreDosFechas(fechaInicio: string, fechaFin: string): number {
    const startDate = new Date(fechaInicio);
    const endDate = new Date(fechaFin);

    // Calculate the difference in years and months
    const yearsDifference = endDate.getFullYear() - startDate.getFullYear();
    const monthsDifference = endDate.getMonth() - startDate.getMonth();

    // Total difference in months
    const totalMonths = yearsDifference * 12 + monthsDifference;

    // Adjust for cases where the end date's day is before the start date's day
    if (endDate.getDate() < startDate.getDate()) {
      return totalMonths - 1;
    }

    return totalMonths;
  }

  public snakeToCamel<T = any>(obj: any): T {
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }

    /*if (Array.isArray(obj)) {
      return obj.map(item => this.snakeToCamel(item)) as T;
    }*/

    const newObj: any = {};
    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        const newKey = key.replace(/(_\w)/g, (m) => m[1].toUpperCase());
        newObj[newKey] = this.snakeToCamel(obj[key]);
      }
    }
    return newObj as T;
  }

  /**
   * Convierte un string de camelCase a snake_case
   * @param str String en camelCase a convertir
   * @returns String en snake_case
   */
  private camelToSnake(str: string): string {
    return str.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
  }

  /**
   * Convierte las claves de un objeto de camelCase a snake_case recursivamente
   * @param obj Objeto a convertir
   * @returns Nuevo objeto con claves en snake_case
   */
  public camelToSnakeKeys<T = any>(obj: T): T {
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }

    if (obj instanceof Date) {
      return obj;
    }

    const newObj: Record<string, any> = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const newKey = this.camelToSnake(key);
        newObj[newKey] = this.camelToSnakeKeys(obj[key]);
      }
    }
    return newObj as T;
  }
