import { Injectable, Injector } from '@angular/core';
import { Conditional, Paginator, SuperService, SuperServiceAllParams, SuperServiceOptions } from './super.service';
import { Credito, CreditoEstado } from '../models/credito.model';
import { firstValueFrom, lastValueFrom } from 'rxjs';
import { VanillaDialogService } from '../services/vanilla-dialog/vanilla-dialog.service';
import { CreditoPago } from '../models/credito.pago.model';
import { LocalStorageService } from '../services/localStorage/local-storage.service';
import { EstadoCuenta, UtilsEstadoCuentaService } from '../main/estado-cuenta/services/utils-estado-cuenta.service';
import { EstadoCuentaService } from './estado.cuenta.service';
import { UtilsService } from '../services/utils.service';
import { SuperFetchDataService } from '../main/reportes/services/fetch-data-generic.service';

@Injectable({
  providedIn: 'any'
})
export class CreditoService extends SuperService<Credito> {
  protected override model: string = "creditos";
  protected override columns: (keyof Credito)[] = [
    'id',
    'aval_id',
    'usuario_id',
    'cliente_id',
    'folio',
    'folio_reestructura',
    'productos_financiero_id',
    'sucursal_id',
    'numero_cuenta',
    'clabe_interbancaria',
    'dictaminado_fecha',
    'dictaminado_por',
    'formalizado_fecha',
    'formalizado_por',
    'liberado_fecha',
    'liberado_por',
    'autorizado_fecha',
    'autorizado_por',
    'datos_llenos_fecha',
    'datos_llenos_por',
    'fecha_deposito',
    'fecha_convenio',
    'fecha_pagare',
    'fecha_amortizacion',
    'fecha_amortizacion_ultima',
    'monto_autorizado',
    'fecha_reestructura',
    'referencia_bancaria',
    'deleted_at',
    'created_at',
    'updated_at',
    'monto_mas_interes',
    'estado',
    'estado_detalle',
    'banco',
    'sesion_id',
    'cuota',
    'carta_instruccion_verificacion',
    'cuenta_contable'
  ];

  constructor(injector: Injector,
    private dialog: VanillaDialogService,
    private localStorage: LocalStorageService,
    private estadoCuentaUtils: UtilsEstadoCuentaService,
    private estadoCuentaController: EstadoCuentaService,
    private utils: UtilsService,
    private fetchData: SuperFetchDataService<Credito>,
  ) {
    super(injector)
    this.fetchData.setController(this)
    this.actualizarEstadosCuentasVencidos()
  }

  public async actualizarEstadosCuentasVencidos() {
    const ids = await this.creditosParaActualizarEstadoCuenta()
    console.info('Creditos con estado cuenta vencido:', ids)
    if (ids.length) {
      console.info('Actualizando estados de cuenta')
      this.actualizarEstadosCuentaMasiva(ids)
    }
  }

  private async creditosParaActualizarEstadoCuenta(): Promise<number[]> {
    return (await firstValueFrom(this.api.get<number[]>(this.url() + "-vencidos", {}, false))).data ?? []
  }

  public async actualizarEstadosCuentaMasiva(creditos: number[]) {
    const creditosData = await this.loadCreditos(creditos)
    const estadosCuenta: EstadoCuenta[] = []
    for (const credito of creditosData) {
      estadosCuenta.push(this.estadoCuentaUtils.calculateEstadoDeCuenta(credito)!)
    }
    await this.updateInChunks(estadosCuenta);
  }

  public async actualizarEstadosCuentaMasivaLocal(creditos: Credito[]) {
    const creditosData = creditos
    const estadosCuenta: EstadoCuenta[] = []
    for (const credito of creditosData) {
      estadosCuenta.push(this.estadoCuentaUtils.calculateEstadoDeCuenta(credito)!)
    }
    await this.updateInChunks(estadosCuenta);
  }

  private async updateInChunks(estadosCuenta: EstadoCuenta[], chunkSize = 100): Promise<void> {
    // Dividir el array en chunks
    for (let i = 0; i < estadosCuenta.length; i += chunkSize) {
      const chunk = estadosCuenta.slice(i, i + chunkSize);
      const res = await this.estadoCuentaController.multipleUpdate(chunk, false, false)
      if(!res) {
        console.error('error al actualizar: ',chunk)
        return;
      }
    }
  }

  public async verificarCartaInstruccion(credito: Credito | undefined) {
    if (!credito) return;
    const fechaVerificacion = credito.carta_instruccion_verificacion ? null : new Date().toISOString().replace('T', ' ').split('.')[0]
    const res = await this.update(credito.id, { carta_instruccion_verificacion: fechaVerificacion }, false)
    if (res.status) {
      credito.carta_instruccion_verificacion = fechaVerificacion
    }
    return res.status
  }

  public async creditoOriginalFromReestructuradoS2c(credito: Credito | undefined, relations: string[] = ['*']) {
    if (!credito?.folio) return;
    if (!this.utils.esReestructura(credito.folio)) return
    const folioOriginal = this.utils.folioOriginalFromCredito(credito)
    return this.first({ folio: folioOriginal, deleted_at: null }, relations)
  }

  private async loadCreditos(creditos: number[]): Promise<Credito[]> {
    const request$ = this.fetchData.getAllData({
      conditionals: [{
        key: 'id',
        operator: 'IN',
        value: creditos.join(',')
      }],
      relations: [
        'convenios.conveniosPagos',
        'creditosPagos',
        'abonos',
        'productosFinancieros.plazos',
        'estadoCuenta',
        'creditoComprobaciones',
        'comprobacionTotalS2c.creditoComprobaciones',
        'juridicos',
        'creditosDespachos.despachos'
      ],
      chunkSize: 50,
    });

    return await lastValueFrom(request$).catch(() => []);
  }

  public async actualizarEstadoCuenta(creditoData: Credito | number | null | undefined) {
    if (!creditoData) return;
    const credito_id = typeof creditoData == 'number' ? creditoData : creditoData.id
    const credito = await this.find(credito_id, [
      'convenios.conveniosPagos',
      'creditosPagos',
      'abonos',
      'productosFinancieros.plazos',
      'estadoCuenta',
      'creditoComprobaciones',
      'comprobacionTotalS2c.creditoComprobaciones',
      'juridicos',
      'creditosDespachos.despachos'
    ])
    this.estadoCuentaUtils.calculateEstadoDeCuenta(credito, true)
  }

  public override async find(id: number, ...params: SuperServiceAllParams<Credito>): Promise<Credito | undefined> {
    const url = this.url() + '/' + id.toString()
    const superOption = params.find((p): p is SuperServiceOptions<Credito> => this.isSuperServiceOptions(p))
    const relations = params.find((p): p is string[] => this.isStringArray(p)) ?? superOption?.relations
    const queryParams = this.queryParamsFromSuperServiceParams(...params)
    const res = (await firstValueFrom(this.api.get<Credito>(url, queryParams, this.loaderFromParamas(params)))).data
    if (relations?.includes('*')) this.parseDetalleEstadoCuenta(res)
    return res
  }

  async validarCredito(credito: Credito): Promise<boolean> {
    const login = this.localStorage.getUser()
    const res = await firstValueFrom(this.api.post('api/access/credito/aprobar', { id: credito.id }))
    if (res.status) {
      credito.autorizado_fecha = credito.autorizado_fecha ? null : (new Date()).toISOString()
      credito.autorizado_por = login
    }
    return res.status
  }

  async dictaminarCredito(credito: Credito): Promise<boolean> {
    const login = this.localStorage.getUser()
    const res = await firstValueFrom(this.api.post('api/access/credito/dictaminar', { id: credito.id }))
    if (res.status) {
      credito.dictaminado_fecha = credito.dictaminado_fecha ? null : (new Date()).toISOString()
      credito.dictaminado_por = credito.dictaminado_fecha ? null : login
    }
    return res.status
  }

  async formalizarCredito(credito: Credito, force: boolean = false): Promise<boolean> {
    const login = this.localStorage.getUser()
    if (credito.liberado_fecha && credito.fecha_convenio && credito.formalizado_fecha) {
      this.dialog.show({
        title: 'No se puede formalizar',
        body: 'El credito se encuentra liberado, ya no se puede modificar.'
      })
      return false;
    }
    credito.formalizado_fecha = (!!credito.formalizado_fecha) ? null : (new Date()).toISOString().substring(0, 10)
    credito.formalizado_por = (!!credito.formalizado_por) ? null : login.id
    const res = await this.update(credito.id, {
      formalizado_fecha: credito.formalizado_fecha,
      formalizado_por: credito.formalizado_por
    })
    console.log(credito)
    return res.status
  }

  async generarPagares(credito: Credito): Promise<boolean> {
    const plazo_id = (credito.productos_financieros?.plazos?.find((plazo) => plazo.plazo_meses == credito?.inversiones_programas?.plazo_solicitado_meses))?.id
    if (!plazo_id) {
      this.dialog.show({
        title: 'Plazo Incorrecto',
        body: 'El plazo solicitado no coincide con ninguno descrito en el producto financiero',
        tipo: 'danger'
      })
      return false
    }
    credito.creditos_pagos = (await firstValueFrom(this.api.get<CreditoPago[]>(`api/ejecucion/creditos/generar_pagos/${credito.id}/${plazo_id}/save`))).data
    return true
  }

  parseDetalleEstadoCuenta(credito?: Credito) {
    if (!credito) return
    credito.estado_cuenta = this.estadoCuentaUtils.getEstadoCuenta(credito, true)
  }

  /**
   * Set a new estado to credito locally if model is passed or just in server if id is passed
   * if undefined return false otherwise if no errors return true
   * @param {Credito|number|undefined} credito
   * @param nuevoEstado 
   * @returns {boolean}
   */
  public async cambiarEstado(credito: Credito | number | undefined, nuevoEstado: CreditoEstado, comentarios: string = ''): Promise<boolean> {
    if (!credito) return false
    const id: number = (typeof credito === 'number') ? credito : credito.id
    const res = await firstValueFrom(this.api.post('api/access/credito/estado', {
      id: id,
      estado: nuevoEstado,
      comentarios: comentarios,
    }, false))
    if (res.status && (typeof credito === 'object')) {
      credito.estado = nuevoEstado
      comentarios = ''
    }
    return res.status
  }

  public async atrasados(
    conditionals: Partial<Credito> | Conditional[] | undefined = undefined,
    paginator: Paginator | undefined = undefined,
    relations: string[] | undefined = undefined,
    extraData: any | undefined = undefined
  ) {
    let params: (string | number | boolean | null)[][] = [];

    if (Array.isArray(conditionals)) {
      params = this.paramsFromConditionals(conditionals);
    } else if (conditionals) {
      params = this.paramsFromModel(conditionals);
    }
    if (!paginator) {
      paginator = {
        page: 1,
        per_page: 99999
      }
    }
    const data = {
      conditionals: JSON.stringify(params),
      relations: JSON.stringify(relations),
      ...paginator,
      ...extraData,
    }
    return firstValueFrom(this.api.get<Credito>('api/ejecucion/creditos/atrasados', data))
  }

  async asociarSesion(credito?: Credito) {
    if (!credito) return
    const url = 'api/access/credito/asociar_sesion'
    const data = {
      sesion_id: credito.sesion_id,
      credito_id: credito.id
    }
    const res = firstValueFrom(this.api.post(url, data))
    console.log(res)
  }

  async autorizarMonto(credito?: Credito) {
    if (!credito) return false
    const url = 'api/access/credito/monto/autorizar'
    const data = {
      id: credito.id,
      monto_autorizado: credito.monto_autorizado
    }
    const res = firstValueFrom(this.api.post(url, data))
    return (await res).status
  }

  async validarDatosBancarios(credito?: Credito) {
    if (!credito) return false
    const url = 'api/access/credito/confirmar_datos_bancarios'
    const res = await firstValueFrom(this.api.post(url, { id: credito.id }))
    if (res.status) {
      credito.datos_bancarios_verificados = credito.datos_bancarios_verificados == 'NO' ? 'SI' : 'NO'
    }
    return res.status
  }

  async marcarLlenado(credito?: Credito) {
    if (!credito) return false
    const login = this.localStorage.getUser()
    const url = 'api/access/credito/datos_llenos'
    const res = await firstValueFrom(this.api.post(url, { id: credito.id }))
    if (res.status) {
      credito.datos_llenos_fecha = credito.datos_llenos_fecha ? null : (new Date()).toISOString()
      credito.datos_llenos_por = credito.datos_llenos_por ? null : login
    }
    return res.status
  }

  async liberarCredito(credito: Credito | undefined, extraLiberacion: any) {
    if (!credito) return false
    const login = this.localStorage.getUser()
    const url = 'api/access/credito/liberar'
    const res = await firstValueFrom(this.api.post(url, { id: credito.id, ...extraLiberacion }))
    if (res.status) {
      credito.liberado_fecha = credito.liberado_fecha ? null : (new Date()).toISOString()
      credito.liberado_por = credito.liberado_por ? null : login
    }
    return res.status
  }
}
